document.addEventListener('DOMContentLoaded', function() {
  const form = document.getElementById('contactForm');
  const fullNameInput = document.getElementById('fullName');
  const emailInput = document.getElementById('email');
  const phoneInput = document.getElementById('phone');
  const emailError = document.getElementById('email-error');

  form.addEventListener('submit', function(event) {
    event.preventDefault();
    validateForm();
  });

  function validateForm() {
    let isValid = true;
    let firstInvalidField = null;

    clearErrors();

    if (!fullNameInput.value.trim()) {
      setInvalid(fullNameInput);
      isValid = false;
      if (!firstInvalidField) firstInvalidField = fullNameInput;
    }

    if (!emailInput.value.trim()) {
      setInvalid(emailInput, 'Error: Email address is required.');
      isValid = false;
      if (!firstInvalidField) firstInvalidField = emailInput;
    } else if (!isValidEmail(emailInput.value)) {
      setInvalid(emailInput, 'Error: Enter a valid email like name@example.com.');
      isValid = false;
      if (!firstInvalidField) firstInvalidField = emailInput;
    }

    if (phoneInput.value.trim() && !isValidPhone(phoneInput.value)) {
      setInvalid(phoneInput, 'Error: Enter a valid phone number.');
      isValid = false;
      if (!firstInvalidField) firstInvalidField = phoneInput;
    }

    if (isValid) {
      handleFormSubmit();
    } else if (firstInvalidField) {
      firstInvalidField.focus();
    }
  }

  function setInvalid(field, errorMsg) {
    field.setAttribute('aria-invalid', 'true');
    if (errorMsg && field.id === 'email') {
      emailError.textContent = errorMsg;
    }
  }

  function clearErrors() {
    fullNameInput.setAttribute('aria-invalid', 'false');
    emailInput.setAttribute('aria-invalid', 'false');
    phoneInput.setAttribute('aria-invalid', 'false');
    emailError.textContent = '';
  }

  function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  function isValidPhone(phone) {
    const phoneRegex = /^(\+?1[\s.-]?)?\(?([0-9]{3})\)?[\s.-]?([0-9]{3})[\s.-]?([0-9]{4})$/;
    return phoneRegex.test(phone.replace(/\s/g, ''));
  }

  function handleFormSubmit() {
    const formData = {
      fullName: fullNameInput.value.trim(),
      email: emailInput.value.trim(),
      phone: phoneInput.value.trim(),
    };

    console.log('Form submitted with data:', formData);
    alert(`Thank you for contacting us, ${formData.fullName}! We'll get back to you soon.`);
    form.reset();
    clearErrors();
  }
});

